import { BooleanColumn, GenericColumn, ScriptColumn, StringColumn, Table, UserRolesColumn } from '../../db'

export const sys_aix_widget = Table({
    name: 'sys_aix_widget',
    extends: 'sys_metadata',
    schema: {
        best_for: StringColumn({
            label: 'Best for',
        }),
        category: StringColumn({
            label: 'Category',
            dropdown: 'dropdown_without_none',
            choices: {
                platform: { label: 'Platform', sequence: 1 },
                custom: { label: 'Custom', sequence: 2 },
            },
        }),
        chat_compatible: BooleanColumn({
            label: 'Chat compatible',
            default: false,
        }),
        client_tools: GenericColumn({
            label: 'Client tools',
            column_type: 'json',
            default: '{}',
        }),
        component: ScriptColumn({
            label: 'Component',
        }),
        component_compile_metadata: GenericColumn({
            label: 'Component compile metadata',
            column_type: 'json',
        }),
        demo_data: StringColumn({
            label: 'Demo data',
        }),
        dependent_widget_ids: StringColumn({
            label: 'Dependent widget IDs',
        }),
        description: StringColumn({
            label: 'Description',
        }),
        id: StringColumn({
            label: 'ID',
            mandatory: true,
        }),
        input_schema: GenericColumn({
            label: 'Input schema',
            column_type: 'json',
            default: '{}',
        }),
        name: StringColumn({
            label: 'Name',
            mandatory: true,
        }),
        required_translations: GenericColumn({
            label: 'Required translations',
            column_type: 'json',
            default: '[]',
        }),
        roles: UserRolesColumn({
            label: 'Roles',
        }),
        script: ScriptColumn({
            label: 'Server script',
            default: `(function(data, options, input) {

})(data, options, input);`,
        }),
        servicenow: BooleanColumn({
            label: 'ServiceNow',
            default: false,
        }),
        template: GenericColumn({
            label: 'Template',
            column_type: 'html_template',
        }),
        type: StringColumn({
            label: 'Type',
        }),
    },
})
